arguments.argument:
in_bbox_data_clear(1)
in_point_data_clear(3)
with(obj_unit)
{
    if ((player>=4 and global.player_control>=4) or (4>player and 4>global.player_control))
    {
        in_bbox_data_add(1, x, y, bbox_left, bbox_right, bbox_top, bbox_bottom, id)
    }
    else
    {
        if drag_ok=0 and skil_number>0
        {
            for(i=0; i!=global.go_number; i+=1)
            {
                if unit_id=ds_list_find_value(global.go_moni, i){in_point_data_add(3, x, y, id); break}
            }
        }
    }
}

in_point_data_clear(4)
with(obj_bil)
{
    if ((player>=4 and global.player_control>=4) or (4>player and 4>global.player_control))
    {
        in_point_data_add(4, x, y, id)
    }
}

with(obj_unit)
{
    if global.player_com[player]
    {
        if moni_go
        {
            if ai=0
            {
                moni_go_waits=1
                ai=1
            }
            //ai
            if moni_go_waits=1
            {
                moni_go_waits_id=in_point_data_find(0, x, y, id, 500)
                if instance_number(moni_go_waits_id)
                {
                    moni_go_waits=2
                }
            }
            else if moni_go_waits=4
            {
                moni_go_waits_id2=in_point_data_find(3, x, y, id, 500)
                if instance_number(moni_go_waits_id2)
                {
                    moni_go_waits=5
                }
            }
        }
        else if unit_s>0
        {
            if attack_waits=1
            {
                attack_unit=in_bbox_data_find(1, x, y, id, attack_range)
                if !instance_number(attack_unit)
                {
                    attack_unit=in_point_data_find(4, x, y, id, attack_range)
                    if instance_number(attack_unit)
                    {
                        attack_waits=2
                    }
                }
                else
                {
                    attack_waits=2
                }
            }
        }
    }
}
